<script setup lang="ts">
import { Activity, Archive, BarChart3, Bell, BookOpenCheck, CalendarDays, ChevronRight, ClipboardCheck, Clock3, GraduationCap, LayoutDashboard, LogOut, Menu, Pencil, Plus, QrCode, Search, Users, X } from '@lucide/vue'
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import api from '../api'
import BrandLogo from '../components/BrandLogo.vue'
import StudentImportModal from '../components/StudentImportModal.vue'
import StudentCardPrintModal from '../components/StudentCardPrintModal.vue'
import { useAuthStore } from '../stores/auth'
import { useLocaleStore } from '../stores/locale'

const auth=useAuthStore();const locale=useLocaleStore();const route=useRoute();const router=useRouter();const loading=ref(true);const importOpen=ref(false);const cardPrintCards=ref<any[]>([]);const issuingCards=ref(false);const revokingCards=ref(false);const menu=ref(false);const data=ref<any>(null);const search=ref('')
const students=ref<any[]>([]);const studentMeta=ref<any>({levels:[],academic_years:[],pagination:{page:1,last_page:1,total:0}});const studentsLoading=ref(false);const selectedStudentIds=ref<string[]>([]);const bulkArchiving=ref(false);const canBulkArchive=computed(()=>Boolean(data.value?.membership.capabilities?.archive_students));const canManageCards=computed(()=>Boolean(data.value?.membership.capabilities?.edit_students));const allVisibleStudentsSelected=computed(()=>students.value.length>0&&students.value.every((student:any)=>selectedStudentIds.value.includes(student.public_id)));const studentOpen=ref(false);const savingStudent=ref(false);const studentError=ref('');const levelFilter=ref('');const studentPage=ref(1);const editingStudent=ref<any>(null)
const studentForm=reactive({name_ar:'',name_en:'',date_of_birth:'',gender:'',phone:'',email:'',academic_year_id:'',educational_level_id:'',guardians:[{name:'',phone:'',email:'',relationship:'father',is_primary:true}],notes:''})
const sections=['overview','students','attendance','schedule','exams','performance']
const section=computed(()=>sections.includes(String(route.params.section))?String(route.params.section):'overview')
const nav=[['overview','Teaching overview',LayoutDashboard],['students','My students',Users],['attendance','Attendance',QrCode],['schedule','My schedule',CalendarDays],['exams','Exams & marks',ClipboardCheck],['performance','Performance',BarChart3]]
const page=computed(()=>({overview:['Teaching overview','Everything you need for today’s classes.'],students:['My students','Students assigned to your teaching groups in this centre.'],attendance:['Attendance','Record and review attendance for today’s sessions.'],schedule:['My schedule','Your classes and teaching commitments.'],exams:['Exams & marks','Create assessments and enter student marks.'],performance:['Performance','Follow progress and identify students who need support.']} as any)[section.value])
const centreName=computed(()=>locale.locale==='ar'?(data.value?.branch.name_ar||data.value?.branch.name_en):(data.value?.branch.name_en||data.value?.branch.name_ar))
async function load(){loading.value=true;try{const response=(await api.get('/dashboard')).data;if(response.membership?.role!=='teacher'){await router.replace('/dashboard');return}data.value=response}finally{loading.value=false}}
async function loadStudents(){studentsLoading.value=true;try{const response=(await api.get('/students',{params:{search:search.value||undefined,level_id:levelFilter.value||undefined,page:studentPage.value}})).data;students.value=response.students;studentMeta.value=response;studentPage.value=response.pagination.page}finally{studentsLoading.value=false}}
function resetStudentPage(){studentPage.value=1;selectedStudentIds.value=[];loadStudents()}
function addGuardian(){if(studentForm.guardians.length<5)studentForm.guardians.push({name:'',phone:'',email:'',relationship:'guardian',is_primary:false})}
function removeGuardian(index:number){if(studentForm.guardians.length<=1)return;const wasPrimary=studentForm.guardians[index].is_primary;studentForm.guardians.splice(index,1);if(wasPrimary)studentForm.guardians[0].is_primary=true}
function setPrimaryGuardian(index:number){studentForm.guardians.forEach((guardian:any,i:number)=>guardian.is_primary=i===index)}
function changeStudentPage(page:number){if(page<1||page>studentMeta.value.pagination.last_page||studentsLoading.value)return;studentPage.value=page;selectedStudentIds.value=[];loadStudents()}
function toggleStudentSelection(publicId:string,checked:boolean){selectedStudentIds.value=checked?[...new Set([...selectedStudentIds.value,publicId])]:selectedStudentIds.value.filter(id=>id!==publicId)}
function toggleVisibleStudents(checked:boolean){const visible=students.value.map((student:any)=>student.public_id);selectedStudentIds.value=checked?[...new Set([...selectedStudentIds.value,...visible])]:selectedStudentIds.value.filter(id=>!visible.includes(id))}
async function archiveSelectedStudents(){if(!selectedStudentIds.value.length||bulkArchiving.value)return;if(!window.confirm(locale.tr('Archive selected students?')+' ('+selectedStudentIds.value.length+')'))return;bulkArchiving.value=true;studentError.value='';try{await api.post('/students/bulk-archive',{public_ids:[...selectedStudentIds.value]});selectedStudentIds.value=[];await loadStudents()}catch(e:any){studentError.value=e.response?.data?.message||'Unable to archive the selected students.'}finally{bulkArchiving.value=false}}
async function issueStudentCards(){if(!selectedStudentIds.value.length||issuingCards.value)return;if(!window.confirm('Issue or replace cards for '+selectedStudentIds.value.length+' selected students? Existing cards will stop working.'))return;issuingCards.value=true;studentError.value='';try{const response=(await api.post('/students/cards/issue',{public_ids:[...selectedStudentIds.value]})).data;cardPrintCards.value=response.cards;selectedStudentIds.value=[]}catch(e:any){studentError.value=e.response?.data?.message||'Unable to issue student cards.'}finally{issuingCards.value=false}}
async function revokeStudentCards(){if(!selectedStudentIds.value.length||revokingCards.value)return;if(!window.confirm('Revoke active cards for '+selectedStudentIds.value.length+' selected students?'))return;revokingCards.value=true;studentError.value='';try{await api.post('/students/cards/revoke',{public_ids:[...selectedStudentIds.value]});selectedStudentIds.value=[]}catch(e:any){studentError.value=e.response?.data?.message||'Unable to revoke student cards.'}finally{revokingCards.value=false}}
function openStudent(student:any=null){studentError.value='';editingStudent.value=student;Object.assign(studentForm,{name_ar:'',name_en:'',date_of_birth:'',gender:'',phone:'',email:'',academic_year_id:'',educational_level_id:'',guardians:[{name:'',phone:'',email:'',relationship:'father',is_primary:true}],notes:''});if(student){Object.assign(studentForm,{name_ar:student.name_ar||'',name_en:student.name_en||'',date_of_birth:student.date_of_birth||'',gender:student.gender||'',phone:student.phone||'',email:student.email||'',academic_year_id:String(student.academic_year?.id||''),educational_level_id:String(student.level?.id||''),guardians:student.guardians?.length?student.guardians.map((guardian:any)=>({...guardian})):student.guardian?[{...student.guardian,email:'',relationship:'guardian',is_primary:true}]:[{name:'',phone:'',email:'',relationship:'father',is_primary:true}],notes:''})}else{studentForm.academic_year_id=String(studentMeta.value.academic_years.find((year:any)=>year.is_active)?.id||'')}studentOpen.value=true}
async function saveStudent(){savingStudent.value=true;studentError.value='';try{const payload={...studentForm,academic_year_id:studentForm.academic_year_id||null,educational_level_id:studentForm.educational_level_id||null,date_of_birth:studentForm.date_of_birth||null,gender:studentForm.gender||null,email:studentForm.email||null,guardians:studentForm.guardians};if(editingStudent.value){await api.patch(`/students/${editingStudent.value.public_id}`,payload)}else{await api.post('/students',payload)}studentOpen.value=false;editingStudent.value=null;Object.assign(studentForm,{name_ar:'',name_en:'',date_of_birth:'',gender:'',phone:'',email:'',academic_year_id:'',educational_level_id:'',guardians:[{name:'',phone:'',email:'',relationship:'father',is_primary:true}],notes:''});await loadStudents()}catch(e:any){studentError.value=Object.values(e.response?.data?.errors||{error:[e.response?.data?.message||'Unable to save this student.']}).flat().join(' ')}finally{savingStudent.value=false}}
const createStudent=saveStudent
async function archiveStudent(student:any){if(!window.confirm(`Archive ${student.name_en||student.name_ar}?`))return;try{await api.post(`/students/${student.public_id}/archive`);await loadStudents()}catch(e:any){studentError.value=e.response?.data?.message||'Unable to archive this student.'}}
async function logout(){await auth.logout();router.replace('/')}
watch(section,value=>{if(value==='students')loadStudents()})
watch([search,levelFilter],()=>{if(section.value==='students')resetStudentPage()})
onMounted(async()=>{await load();if(section.value==='students')await loadStudents()})
</script>

<template><div class="app-shell teacher-shell"><aside :class="{open:menu}"><div class="sidebar-head"><BrandLogo light/><button @click="menu=false"><X/></button></div><div class="teacher-identity"><span><GraduationCap/></span><div><small>TEACHER WORKSPACE</small><b>{{centreName||'Loading…'}}</b></div></div><nav><small>TEACHING</small><RouterLink v-for="([key,label,Icon]) in nav" :key="String(key)" :to="`/teacher/${key}`" :class="{active:section===key}" @click="menu=false"><component :is="Icon"/>{{label}}</RouterLink><small>QUICK ACCESS</small><a href="#" @click.prevent="router.push('/teacher/attendance')"><QrCode/>Scan attendance</a><a href="#" @click.prevent="router.push('/teacher/exams')"><BookOpenCheck/>Enter marks</a></nav><div class="sidebar-foot"><span>{{auth.user?.name.slice(0,2).toUpperCase()}}</span><div><b>{{auth.user?.name}}</b><small>{{data?.membership.role_name||'Teacher'}}</small></div><button title="Sign out" @click="logout"><LogOut/></button></div></aside>
  <main class="dashboard-main"><header><button class="mobile-nav" @click="menu=true"><Menu/></button><div class="global-search"><Search/><input v-model="search" placeholder="Search your students…"><kbd>TEACHER</kbd></div><div class="header-actions"><span class="teacher-centre-pill"><GraduationCap/>{{centreName}}</span><button><Bell/></button></div></header><div v-if="loading" class="loading-state"><span></span>Preparing your teaching workspace…</div><div v-else class="dashboard-content teacher-content">
    <div class="teacher-page-head"><div><span>{{centreName}} · {{data.academic_year?.name||'Academic setup'}}</span><h1>{{page[0]}}</h1><p>{{page[1]}}</p></div><button v-if="section==='students'" class="button primary" @click="openStudent()"><Plus/>Add student</button><button v-if="section==='attendance'" class="button primary"><QrCode/>Start attendance</button><button v-if="section==='exams'" class="button primary"><Plus/>Create exam</button></div>
    <template v-if="section==='overview'"><section class="teacher-stats"><article><span><Users/></span><small>MY STUDENTS</small><b>0</b><em>Ready for your first group</em></article><article><span><CalendarDays/></span><small>TODAY'S CLASSES</small><b>0</b><em>No sessions scheduled</em></article><article><span><QrCode/></span><small>ATTENDANCE</small><b>—</b><em>Nothing to record yet</em></article><article><span><ClipboardCheck/></span><small>MARKING</small><b>0</b><em>No pending marks</em></article></section><section class="teacher-grid"><article class="teacher-card"><div class="teacher-card-head"><div><small>TODAY</small><h2>Your teaching schedule</h2></div><RouterLink to="/teacher/schedule">Open schedule <ChevronRight/></RouterLink></div><div class="teacher-empty"><CalendarDays/><b>No classes scheduled today</b><p>Your upcoming classes will appear here once teaching groups and schedules are created.</p></div></article><article class="teacher-card"><div class="teacher-card-head"><div><small>QUICK ACTIONS</small><h2>Keep teaching moving</h2></div><Activity/></div><div class="teacher-actions"><RouterLink to="/teacher/attendance"><span><QrCode/></span><div><b>Record attendance</b><small>Open the scanner or mark manually</small></div><ChevronRight/></RouterLink><RouterLink to="/teacher/exams"><span><ClipboardCheck/></span><div><b>Enter marks</b><small>Continue an assessment</small></div><ChevronRight/></RouterLink><RouterLink to="/teacher/students"><span><Users/></span><div><b>Open student list</b><small>View your assigned learners</small></div><ChevronRight/></RouterLink></div></article></section></template>
    <template v-else-if="section==='students'"><form class="teacher-toolbar" @submit.prevent="resetStudentPage"><div><Search/><input v-model="search" placeholder="Search by student name or code"></div><select v-model="levelFilter"><option value="">All levels</option><option v-for="level in studentMeta.levels" :key="level.id" :value="level.id">{{locale.locale==='ar'?(level.name_ar||level.name_en):(level.name_en||level.name_ar)}}</option></select><button class="button secondary">Search</button><button v-if="data.membership.capabilities?.import_students" type="button" class="button secondary" @click="importOpen=true">{{locale.tr('Import students')}}</button></form><div v-if="studentsLoading" class="teacher-table-loading">Loading students…</div><section v-else-if="students.length" class="teacher-card student-directory"><div class="student-directory-head"><span>{{studentMeta.pagination.total}} students</span><small>Active centre · page {{studentMeta.pagination.page}} of {{studentMeta.pagination.last_page}}</small><button v-if="canManageCards" class="button secondary" :disabled="!selectedStudentIds.length||issuingCards" @click="issueStudentCards">{{issuingCards?'Preparing cards…':'Issue / replace cards ('+selectedStudentIds.length+')'}}</button><button v-if="canManageCards" class="button secondary" :disabled="!selectedStudentIds.length||revokingCards" @click="revokeStudentCards">{{revokingCards?'Revoking…':'Revoke cards'}}</button><button v-if="canBulkArchive" class="button secondary" :disabled="!selectedStudentIds.length||bulkArchiving" @click="archiveSelectedStudents">{{bulkArchiving?locale.tr('Archiving…'):locale.tr('Archive selected')+' ('+selectedStudentIds.length+')'}}</button></div><div class="student-table"><div class="student-row student-row-head"><span><input v-if="canBulkArchive||canManageCards" type="checkbox" :checked="allVisibleStudentsSelected" :aria-label="locale.tr('Select all students on this page')" @change="toggleVisibleStudents(($event.target as HTMLInputElement).checked)"> Student</span><span>Level</span><span>Guardian</span><span>Status</span><span>Actions</span></div><article v-for="student in students" :key="student.public_id" class="student-row"><span class="student-person"><input v-if="canBulkArchive||canManageCards" type="checkbox" :checked="selectedStudentIds.includes(student.public_id)" :aria-label="locale.tr('Select student')" @change="toggleStudentSelection(student.public_id,($event.target as HTMLInputElement).checked)"><i>{{(student.name_en||student.name_ar).slice(0,2).toUpperCase()}}</i><b>{{locale.locale==='ar'?(student.name_ar||student.name_en):(student.name_en||student.name_ar)}}<small>{{student.student_code}}</small></b></span><span>{{student.level?(locale.locale==='ar'?(student.level.name_ar||student.level.name_en):(student.level.name_en||student.level.name_ar)):'Not assigned'}}</span><span class="guardian-cell"><b>{{student.guardian?.name||'Not set'}}</b><small>{{student.guardian?.phone||'—'}}</small></span><span><em class="status-pill active">{{student.status}}</em></span><span class="student-actions"><button type="button" :title="locale.tr('Edit student and guardians')" :aria-label="locale.tr('Edit student and guardians')" @click="openStudent(student)"><Pencil/></button></span></article></div><div v-if="studentMeta.pagination.last_page>1" class="student-pagination"><button class="button secondary" :disabled="studentMeta.pagination.page<=1" @click="changeStudentPage(studentMeta.pagination.page-1)">Previous</button><span>Page {{studentMeta.pagination.page}} of {{studentMeta.pagination.last_page}}</span><button class="button secondary" :disabled="studentMeta.pagination.page>=studentMeta.pagination.last_page" @click="changeStudentPage(studentMeta.pagination.page+1)">Next</button></div></section><section v-else class="teacher-card teacher-list-empty"><Users/><h2>Your student list is ready</h2><p>Register the first student with their guardian and academic level. The record will belong only to this centre.</p><button class="button secondary" @click="openStudent()"><Plus/>Add the first student</button></section></template>
    <template v-else-if="section==='attendance'"><section class="attendance-launch"><span><QrCode/></span><small>FAST CLASSROOM FLOW</small><h2>Start today’s attendance</h2><p>Select a scheduled session, then scan student cards or mark attendance manually. Duplicate scans will be safely ignored.</p><div><button class="button primary"><QrCode/>Open scanner</button><button class="button secondary">Mark manually</button></div></section><section class="teacher-card"><div class="teacher-card-head"><div><small>RECENT SESSIONS</small><h2>Attendance history</h2></div><Clock3/></div><div class="teacher-empty compact"><Activity/><b>No attendance sessions yet</b><p>Completed sessions will appear here for review.</p></div></section></template>
    <template v-else-if="section==='schedule'"><section class="teacher-card"><div class="teacher-card-head"><div><small>WEEKLY VIEW</small><h2>Your class schedule</h2></div><CalendarDays/></div><div class="week-strip"><span v-for="day in ['Sun','Mon','Tue','Wed','Thu','Fri','Sat']" :key="day"><b>{{day}}</b><small>0 classes</small></span></div><div class="teacher-empty compact"><CalendarDays/><b>No classes planned</b><p>Your administrator can assign teaching groups and weekly times.</p></div></section></template>
    <template v-else-if="section==='exams'"><section class="teacher-card teacher-list-empty"><ClipboardCheck/><h2>No assessments yet</h2><p>Create an exam, choose its subject and teaching groups, then enter marks with a keyboard-friendly workflow.</p><button class="button primary"><Plus/>Create first exam</button></section></template>
    <template v-else><section class="teacher-stats performance-stats"><article><span><BarChart3/></span><small>CLASS AVERAGE</small><b>—</b><em>Awaiting results</em></article><article><span><GraduationCap/></span><small>IMPROVING</small><b>0</b><em>No trend data yet</em></article><article><span><Activity/></span><small>NEEDS SUPPORT</small><b>0</b><em>No alerts yet</em></article></section><section class="teacher-card teacher-list-empty"><BarChart3/><h2>Performance insights will grow here</h2><p>Published exam results will unlock subject trends, student progress and early support signals.</p></section></template>
  </div></main>
  <div v-if="studentOpen" class="modal-backdrop" @click.self="studentOpen=false"><section class="centre-modal student-modal" role="dialog" aria-modal="true"><button class="modal-close" @click="studentOpen=false"><X/></button><span class="modal-icon"><Users/></span><span class="eyebrow">{{editingStudent?locale.tr('EDIT STUDENT'):locale.tr('NEW STUDENT')}} · {{centreName}}</span><h2>{{editingStudent?locale.tr('Edit student details'):locale.tr('Register a student')}}</h2><p>{{editingStudent?locale.tr('Update the student record, enrolment and guardian contacts.'):locale.tr('Create the student, primary guardian and current enrolment together.')}}</p><form @submit.prevent="createStudent"><div class="modal-grid"><label>{{locale.tr('Student name in Arabic')}}<input v-model="studentForm.name_ar" required autocomplete="off" :placeholder="locale.locale==='ar'?'اسم الطالب':locale.tr('Student name in Arabic')"></label><label>{{locale.tr('Student name in English')}}<input v-model="studentForm.name_en" :placeholder="locale.tr('Student name in English')"></label><label>{{locale.tr('Date of birth')}}<input v-model="studentForm.date_of_birth" type="date"></label><label>{{locale.tr('Gender')}}<select v-model="studentForm.gender"><option value="">{{locale.tr('Not specified')}}</option><option value="male">{{locale.tr('Male')}}</option><option value="female">{{locale.tr('Female')}}</option></select></label><label>{{locale.tr('Academic year')}}<select v-model="studentForm.academic_year_id"><option value="">{{locale.tr('Not assigned')}}</option><option v-for="year in studentMeta.academic_years" :key="year.id" :value="year.id">{{year.name}}</option></select></label><label>{{locale.tr('Educational level')}}<select v-model="studentForm.educational_level_id"><option value="">{{locale.tr('Not assigned')}}</option><option v-for="level in studentMeta.levels" :key="level.id" :value="level.id">{{level.name_en||level.name_ar}}</option></select></label><label>{{locale.tr('Student phone')}}<input v-model="studentForm.phone" inputmode="tel"></label><label>{{locale.tr('Student email')}}<input v-model="studentForm.email" type="email"></label><div v-for="(guardian,index) in studentForm.guardians" :key="index" class="student-guardian-block full"><div class="student-form-divider"><span>{{locale.tr(guardian.is_primary?'PRIMARY GUARDIAN':'ADDITIONAL GUARDIAN')}}</span><button v-if="!guardian.is_primary" type="button" class="text-button" @click="setPrimaryGuardian(index)">{{locale.tr('Make primary')}}</button><button v-if="studentForm.guardians.length>1" type="button" class="text-button" @click="removeGuardian(index)">{{locale.tr('Remove')}}</button></div><div class="student-guardian-fields"><label>{{locale.tr('Guardian name')}}<input v-model="guardian.name" required></label><label>{{locale.tr('Guardian phone')}}<input v-model="guardian.phone" required inputmode="tel"></label><label>{{locale.tr('Relationship')}}<select v-model="guardian.relationship" required><option value="father">{{locale.tr('Father')}}</option><option value="mother">{{locale.tr('Mother')}}</option><option value="guardian">{{locale.tr('Guardian')}}</option><option value="other">{{locale.tr('Other')}}</option></select></label><label>{{locale.tr('Guardian email')}}<input v-model="guardian.email" type="email"></label></div></div><button type="button" class="button secondary full" :disabled="studentForm.guardians.length>=5" @click="addGuardian">{{locale.tr('Add another guardian')}}</button><label class="full">{{locale.tr('Notes')}}<input v-model="studentForm.notes" :placeholder="locale.tr('Optional notes')"></label></div><div v-if="studentError" class="form-error">{{studentError}}</div><div class="modal-actions"><button type="button" class="button secondary" @click="studentOpen=false">{{locale.tr('Cancel')}}</button><button class="button primary" :disabled="savingStudent">{{savingStudent?locale.tr('Saving…'):editingStudent?locale.tr('Save changes'):locale.tr('Register student')}}<Plus/></button></div></form></section></div>
</div><StudentImportModal :open="importOpen" @close="importOpen=false" @completed="loadStudents"/><StudentCardPrintModal v-if="cardPrintCards.length" :cards="cardPrintCards" :centre-name="centreName" @close="cardPrintCards=[]"/></template>
